// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {SafeERC20, IERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title FixedOwnerCollectProxy
 * @author Your Name
 * @notice The most streamlined and secure version of the collection proxy.
 * @dev This contract locks both the authorized caller AND the recipient to a single address:
 *      the creator of the contract. This creates a trustless, single-purpose tool.
 *      - The constructor takes no arguments.
 *      - The deployer's address (`msg.sender`) is stored as the immutable `i_owner`.
 *      - Only the `i_owner` can call the `collect` function.
 *      - All collected tokens are sent only to the `i_owner`.
 */
contract FixedOwnerCollectProxy {
    using SafeERC20 for IERC20;

    // --- Immutable State Variable ---
    /**
     * @notice The contract owner. This address is both the only authorized caller
     *         and the sole recipient of the funds. It is set to the deployer's address.
     */
    address public immutable i_owner;

    // --- Event ---
    event Collected(address indexed token, address indexed to, uint256 amount);

    // --- Constructor ---
    /**
     * @notice Sets the owner to the contract deployer's address.
     * @dev This parameterless constructor simplifies deployment and maximizes security.
     */
    constructor() {
        i_owner = msg.sender;
    }

    // --- Main Function ---
    /**
     * @notice Collects the entire balance of a specific ERC20 token to the owner's address.
     * @dev Can only be called by `i_owner`.
     * @param token The address of the ERC20 token contract.
     */
    function collect(address token) external {
        // Gas-efficient balance check.
        uint256 balance = IERC20(token).balanceOf(address(this));

        if (balance > 0) {
            // Funds are securely transferred to the immutable owner address.
            IERC20(token).safeTransfer(i_owner, balance);
            emit Collected(token, i_owner, balance);
        }
    }
}

